import type { ClaimCategory, ClaimRecord } from "./types";

/**
 * Second batch of source-backed statements: medicines whose US label has no patient-directed Medication Guide.
 * Each statement rests on one short exact passage of the stored US prescribing information (the sections that
 * speak to the prescriber, or tell the prescriber what to counsel patients about). The wording restates that
 * passage in plain language for a patient. It adds no dose, number, warning or condition the passage lacks, and
 * explains a medical term only briefly where a lay reader would otherwise be stuck.
 *
 * US labels only. None is an Indian label. None has been reviewed.
 */
export type Make = (slug: string, category: ClaimCategory, loinc: string, passage: string, wording: string, limitations?: string[], replacesRule?: string) => ClaimRecord;

const IND = "34067-9";
const DOSE = "34068-7";
const CONTRA = "34070-3";
const WARN = "34071-1";
const ADVERSE = "34084-4";
const PC = "34076-0";
const BOX = "34066-1";
const INTER = "34073-7";

const LIST_PI = ["US prescribing information, which is written for clinicians: this restates it in plain words.", "The label lists events reported in people taking the medicine and gives no frequencies.", "US label only: Indian approval, strengths and warnings may differ."];

export function batch2(c: Make): ClaimRecord[] {
  return [
    /* ---- risperidone tablets ---- */
    c("risperidone", "used-for", IND, "Risperidone tablets are an atypical antipsychotic indicated for: Treatment of schizophrenia (1.1) As monotherapy or adjunctive therapy with lithium or valproate, for the treatment of acute manic or mixed episodes associated with Bipolar I Disorder (1.2) Treatment of irritability associated with autistic disorder (1.3)", "Risperidone is an atypical antipsychotic. The US label lists these uses: schizophrenia; acute manic or mixed episodes of bipolar I disorder (on its own, or together with lithium or valproate); and irritability associated with autistic disorder."),
    c("risperidone", "precaution", BOX, "Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death. Risperidone is not approved for the treatment of patients with dementia-related psychosis.", "Elderly people with dementia-related psychosis who are treated with antipsychotic medicines are at an increased risk of death. Risperidone is not approved for treating dementia-related psychosis."),
    c("risperidone", "contraindication", CONTRA, "Risperidone tablets are contraindicated in patients with a known hypersensitivity to either risperidone or paliperidone, or to any of the excipients in the risperidone tablets formulation.", "Do not take it if you are known to be allergic (hypersensitive) to risperidone, to paliperidone, or to any other ingredient in the tablets."),
    c("risperidone", "urgent-help", PC, "Counsel patients about a potentially fatal adverse reaction, Neuroleptic Malignant Syndrome (NMS), that has been reported in association with administration of antipsychotic drugs. Advise patients, family members, or caregivers to contact the healthcare provider or report to the emergency room if they experience signs and symptoms of NMS, including hyperpyrexia, muscle rigidity, altered mental status including delirium, and evidence of autonomic instability (irregular pulse or blood pressure, tachycardia, diaphoresis, and cardiac dysrhythmia)", "Antipsychotic medicines have been linked to a potentially fatal reaction called neuroleptic malignant syndrome (NMS). Contact your healthcare provider or go to the emergency room if you or a family member have a very high fever, muscle stiffness, confusion or delirium, an irregular pulse or blood pressure, a fast heartbeat, sweating or an irregular heart rhythm."),
    c("risperidone", "side-effects", PC, "Counsel patients on the signs and symptoms of tardive dyskinesia and to contact their healthcare provider if these abnormal movements occur", "Tardive dyskinesia is a problem of abnormal movements that can be linked to antipsychotic medicines. Contact your healthcare provider if you notice abnormal movements."),
    c("risperidone", "side-effects", PC, "Educate patients about the risk of metabolic changes, how to recognize symptoms of hyperglycemia and diabetes mellitus, and the need for specific monitoring, including blood glucose, lipids, and weight", "Risperidone can cause metabolic changes. Your healthcare provider should explain how to recognise the symptoms of high blood sugar (hyperglycemia) and diabetes, and why your blood sugar, blood fats (lipids) and weight need to be monitored."),
    c("risperidone", "precaution", PC, "Educate patients about the risk of orthostatic hypotension and syncope, particularly at the time of initiating treatment, re-initiating treatment, or increasing the dose", "It can cause low blood pressure when you stand up (orthostatic hypotension) and fainting (syncope), particularly when treatment is started or restarted, or when the dose is increased."),
    c("risperidone", "monitoring", PC, "Advise patients with a pre-existing low WBC or a history of drug induced leukopenia/neutropenia they should have their CBC monitored while taking risperidone", "If you already have a low white blood cell count, or have had a drop in white cells caused by a medicine (leukopenia or neutropenia), you should have your blood count (CBC) monitored while taking risperidone."),
    c("risperidone", "side-effects", PC, "Counsel patients on signs and symptoms of hyperprolactinemia that may be associated with chronic use of risperidone. Advise them to seek medical attention if they experience any of the following: amenorrhea or galactorrhea in females, erectile dysfunction or gynecomastia in males", "Long-term use may raise the hormone prolactin (hyperprolactinemia). Seek medical attention if a woman has missed periods (amenorrhea) or breast milk production (galactorrhea), or if a man has erectile dysfunction or breast enlargement (gynecomastia)."),
    c("risperidone", "precaution", PC, "Caution patients about performing activities requiring mental alertness, such as operating hazardous machinery, or operating a motor vehicle until they are reasonably certain that risperidone therapy does not affect them adversely", "Do not do activities that need you to be mentally alert, such as operating hazardous machinery or driving, until you are reasonably certain that risperidone does not affect you badly."),
    c("risperidone", "urgent-help", PC, "Advise patients of the possibility of painful or prolonged penile erections (priapism). Instruct the patient to seek immediate medical attention in the event of priapism", "A painful or prolonged erection (priapism) is possible. Seek immediate medical attention if it happens."),
    c("risperidone", "precaution", PC, "Counsel patients regarding appropriate care in avoiding overheating and dehydration", "Take care to avoid overheating and dehydration."),
    c("risperidone", "interactions", PC, "Advise patients to inform their healthcare providers if they are taking, or plan to take any prescription or over-the-counter drugs, as there is a potential for interactions", "Tell your healthcare provider about any prescription or over-the-counter medicine you are taking or plan to take, because interactions are possible."),
    c("risperidone", "interactions", INTER, "Carbamazepine and other enzyme inducers decrease plasma concentrations of risperidone. Increase the risperidone dose up to double the patient’s usual dose. Titrate slowly.", "Carbamazepine and similar medicines lower the level of risperidone in the blood. The label says the risperidone dose is then increased, by up to double the usual dose, slowly. Your prescriber decides this, not you."),
    c("risperidone", "interactions", INTER, "Fluoxetine, paroxetine, and other CYP2D6 enzyme inhibitors increase plasma concentrations of risperidone. Reduce the initial dose. Do not exceed a final dose of 8 mg per day of risperidone.", "Fluoxetine, paroxetine and similar medicines raise the level of risperidone in the blood. The label says the starting dose should be reduced and the final dose should not exceed 8 mg a day. Your prescriber decides this, not you."),
    c("risperidone", "precaution", PC, "Advise patients to avoid alcohol while taking risperidone", "Avoid alcohol while taking risperidone."),
    c("risperidone", "precaution", PC, "Advise patients to notify their healthcare provider if they become pregnant or intend to become pregnant during treatment with risperidone. Advise patients that risperidone may cause extrapyramidal and/or withdrawal symptoms in a neonate.", "Tell your healthcare provider if you become pregnant or intend to become pregnant during treatment. Risperidone may cause extrapyramidal symptoms (movement problems) and/or withdrawal symptoms in a newborn baby."),
    c("risperidone", "precaution", PC, "Advise breastfeeding women using risperidone to monitor infants for somnolence, failure to thrive, jitteriness, and extrapyramidal symptoms (tremors and abnormal muscle movements) and to seek medical care if they notice these signs", "If you are breastfeeding while using risperidone, watch your baby for unusual sleepiness, poor growth or feeding (failure to thrive), jitteriness, and tremors or abnormal muscle movements, and seek medical care if you notice these signs."),
    c("risperidone", "side-effects", ADVERSE, "The most common adverse reactions in clinical trials (> 5% and twice placebo) were parkinsonism, akathisia, dystonia, tremor, sedation, dizziness, anxiety, blurred vision, nausea, vomiting, upper abdominal pain, stomach discomfort, dyspepsia, diarrhea, salivary hypersecretion, constipation, dry mouth, increased appetite, increased weight, fatigue, rash, nasal congestion, upper respiratory tract infection, nasopharyngitis, and pharyngolaryngeal pain.", "The most common side effects in trials (more than 5% of people and twice as often as with a dummy tablet) were: parkinsonism (movement problems like those of Parkinson's disease), akathisia (inner restlessness), dystonia (muscle spasms), tremor, sedation, dizziness, anxiety, blurred vision, nausea, vomiting, pain in the upper abdomen, stomach discomfort, indigestion, diarrhoea, extra saliva, constipation, dry mouth, increased appetite, weight gain, tiredness, rash, nasal congestion, upper respiratory tract infection, a cold-like nose and throat infection (nasopharyngitis) and throat pain.", ["US prescribing information, which is written for clinicians: this restates it in plain words.", "Figures come from US trials and cannot predict how common a side effect is for any one person.", "US label only: Indian approval, strengths and warnings may differ."]),

    /* ---- haloperidol tablets ---- */
    c("haloperidol", "used-for", IND, "Haloperidol tablets, USP are indicated for use in the management of manifestations of psychotic disorders.", "Haloperidol is used in the management of the symptoms of psychotic disorders."),
    c("haloperidol", "used-for", IND, "Haloperidol tablets are indicated for the control of tics and vocal utterances of Tourette’s Disorder in children and adults.", "It is also used to control the tics and vocal utterances (sounds or words that cannot be held back) of Tourette's disorder in children and adults."),
    c("haloperidol", "precaution", BOX, "Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death.", "Elderly people with dementia-related psychosis who are treated with antipsychotic medicines are at an increased risk of death. The label says haloperidol is not approved for treating dementia-related psychosis."),
    c("haloperidol", "contraindication", CONTRA, "Haloperidol tablets are contraindicated in severe toxic central nervous system depression or comatose states from any cause and in individuals who are hypersensitive to this drug or have Parkinson’s disease.", "Do not take it if you are in a coma or have severe toxic depression of the central nervous system (a dangerous slowing of brain function) from any cause, if you are hypersensitive (allergic) to it, or if you have Parkinson's disease."),
    c("haloperidol", "how-to-take", DOSE, "dosage should be individualized according to the needs and response of each patient.", "Your dose should be set for you, according to your needs and how you respond."),
    c("haloperidol", "how-to-take", DOSE, "Children, debilitated or geriatric patients, as well as those with a history of adverse reactions to antipsychotic drugs, may require less haloperidol.", "Children, people who are debilitated or elderly, and people who have had side effects from antipsychotic medicines before may need less haloperidol."),
    c("haloperidol", "side-effects", ADVERSE, "EPS during the administration of haloperidol have been reported frequently, often during the first few days of treatment. EPS can be categorized generally as Parkinson-like symptoms, akathisia, or dystonia (including opisthotonos and oculogyric crisis).", "Extrapyramidal symptoms (EPS, a group of movement problems) have been reported frequently with haloperidol, often during the first few days of treatment. They include Parkinson-like symptoms, akathisia (inner restlessness) and dystonia (muscle spasms)."),
    c("haloperidol", "urgent-help", ADVERSE, "Symptoms of dystonia, prolonged abnormal contractions of muscle groups, may occur in susceptible individuals during the first few days of treatment. Dystonic symptoms include: spasm of the neck muscles, sometimes progressing to tightness of the throat, swallowing difficulty, difficulty breathing, and/or protrusion of the tongue.", "Dystonia (long muscle spasms) may occur in susceptible people during the first few days of treatment. Symptoms include spasm of the neck muscles, sometimes progressing to tightness of the throat, trouble swallowing, trouble breathing and/or the tongue sticking out. Get medical help if this happens."),
    c("haloperidol", "side-effects", ADVERSE, "Tardive Dyskinesia As with all antipsychotic agents, haloperidol has been associated with persistent dyskinesias. Tardive dyskinesia, a syndrome consisting of potentially irreversible, involuntary, dyskinetic movements, may appear in some patients on long-term therapy or may occur after drug therapy has been discontinued.", "Like all antipsychotics, haloperidol has been linked to persistent abnormal movements. Tardive dyskinesia is a condition of potentially irreversible, involuntary movements that may appear in some people on long-term treatment, or after the medicine has been stopped."),
    c("haloperidol", "side-effects", ADVERSE, "The syndrome is characterized by rhythmical involuntary movements of tongue, face, mouth or jaw (e.g., protrusion of tongue, puffing of cheeks, puckering of mouth, chewing movements).", "Tardive dyskinesia shows as rhythmical involuntary movements of the tongue, face, mouth or jaw, for example the tongue sticking out, puffing of the cheeks, puckering of the mouth or chewing movements."),
    c("haloperidol", "side-effects", ADVERSE, "Tachycardia, hypotension, and hypertension have been reported. QT prolongation and/or ventricular arrhythmias have also been reported, in addition to ECG pattern changes compatible with the polymorphous configuration of Torsades de pointes, and may occur more frequently with high doses and in predisposed patients", "Fast heartbeat, low blood pressure and high blood pressure have been reported. Heart rhythm changes (QT prolongation, and ventricular arrhythmias including a pattern called Torsades de pointes) have also been reported and may occur more often with high doses and in people who are predisposed to them."),
    c("haloperidol", "side-effects", ADVERSE, "Neuroleptic malignant syndrome (NMS), hyperpyrexia and heat stroke have been reported with haloperidol.", "Neuroleptic malignant syndrome (NMS, a rare, serious reaction to antipsychotics), a very high fever (hyperpyrexia) and heat stroke have been reported with haloperidol."),
    c("haloperidol", "side-effects", ADVERSE, "Anorexia, constipation, diarrhea, hypersalivation, dyspepsia, nausea and vomiting.", "Stomach and bowel effects listed: loss of appetite, constipation, diarrhoea, too much saliva, indigestion, nausea and vomiting."),
    c("haloperidol", "side-effects", ADVERSE, "Dry mouth, blurred vision, urinary retention, diaphoresis and priapism.", "Other effects listed: dry mouth, blurred vision, difficulty passing urine (urinary retention), sweating and priapism (a painful, prolonged erection)."),
    c("haloperidol", "stopping", ADVERSE, "However, some patients on maintenance treatment experience transient dyskinetic signs after abrupt withdrawal. In certain of these cases the dyskinetic movements are indistinguishable from the syndrome described below under “Tardive Dyskinesia” except for duration. It is not known whether gradual withdrawal of antipsychotic drugs will reduce the rate of occurrence of withdrawal emergent neurological signs but until further evidence becomes available, it seems reasonable to gradually withdraw use of haloperidol.", "Some people on long-term treatment get temporary abnormal movements (dyskinetic signs) after stopping suddenly. It is not known whether stopping gradually reduces this, but the label says it seems reasonable to stop haloperidol gradually. Do not stop without talking to your prescriber."),

    /* ---- chlorpromazine tablets ---- */
    c("chlorpromazine", "used-for", IND, "For the management of manifestations of psychotic disorders. For the treatment of schizophrenia. To control nausea and vomiting. For relief of restlessness and apprehension before surgery.", "Chlorpromazine is used to manage the symptoms of psychotic disorders, to treat schizophrenia, to control nausea and vomiting, and to relieve restlessness and apprehension (worry) before surgery."),
    c("chlorpromazine", "used-for", IND, "For acute intermittent porphyria. As an adjunct in the treatment of tetanus. To control the manifestations of the manic type of manic-depressive illness. For relief of intractable hiccups.", "The label also lists these uses: acute intermittent porphyria, as an add-on treatment for tetanus, to control the manic type of manic-depressive illness (bipolar disorder), and to relieve hiccups that will not stop (intractable hiccups)."),
    c("chlorpromazine", "precaution", BOX, "Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death.", "Elderly people with dementia-related psychosis who are treated with antipsychotic medicines are at an increased risk of death."),
    c("chlorpromazine", "contraindication", CONTRA, "Do not use in patients with known hypersensitivity to phenothiazines. Do not use in comatose states or in the presence of large amounts of central nervous system depressants (alcohol, barbiturates, narcotics, etc.).", "Do not use it if you are known to be hypersensitive (allergic) to phenothiazines (the group of medicines chlorpromazine belongs to). Do not use it in a coma, or when there are large amounts of medicines or substances in the body that slow the brain (alcohol, barbiturates, narcotics and similar)."),
    c("chlorpromazine", "onset", DOSE, "Maximum improvement may not be seen for weeks or even months.", "For psychotic disorders, the label says maximum improvement may not be seen for weeks or even months.", ["This is stated for the treatment of psychotic disorders, not for every use of chlorpromazine.", "US prescribing information, which is written for clinicians: this restates it in plain words.", "US label only: Indian approval, strengths and warnings may differ."], "onset-works-gradually"),
    c("chlorpromazine", "how-to-take", DOSE, "Adjust dosage to individual and the severity of his condition", "Your dose is adjusted to you and the severity of your condition. Your prescriber decides it, not you."),
    c("chlorpromazine", "how-to-take", DOSE, "In continued therapy, gradually reduce dosage to the lowest effective maintenance level, after symptoms have been controlled for a reasonable period.", "In continued treatment, the dose is gradually reduced to the lowest level that keeps working, once symptoms have been controlled for a reasonable period."),
    c("chlorpromazine", "how-to-take", DOSE, "In general, dosages in the lower range are sufficient for most elderly patients. Since they appear to be more susceptible to hypotension and neuromuscular reactions, such patients should be observed closely.", "Elderly people usually need doses in the lower range. They appear more susceptible to low blood pressure and muscle and nerve reactions, so they should be watched closely."),
    c("chlorpromazine", "side-effects", ADVERSE, "Usually mild to moderate, may occur, particularly during the first or second week, after which it generally disappears. If troublesome, dosage may be lowered.", "Drowsiness is usually mild to moderate and may occur, particularly in the first or second week, after which it generally goes away. If it is troublesome, the dose may be lowered."),
    c("chlorpromazine", "side-effects", ADVERSE, "Overall incidence has been low, regardless of indication or dosage. Most investigators conclude it is a sensitivity reaction. Most cases occur between the second and fourth weeks of therapy.", "Jaundice (yellowing of the skin and eyes) is uncommon. Most investigators conclude it is a sensitivity reaction, and most cases occur between the second and fourth weeks of treatment."),
    c("chlorpromazine", "side-effects", ADVERSE, "It is usually promptly reversible on withdrawal of the medication; however, chronic jaundice has been reported.", "Jaundice is usually promptly reversible when the medicine is withdrawn, but chronic (long-lasting) jaundice has been reported."),
    c("chlorpromazine", "side-effects", ADVERSE, "Hematological Disorders: including agranulocytosis, eosinophilia, leukopenia, hemolytic anemia, aplastic anemia, thrombocytopenic purpura and pancytopenia have been reported.", "Blood disorders have been reported, including agranulocytosis and leukopenia (low white blood cells), hemolytic and aplastic anemia (low red blood cells), thrombocytopenic purpura (low platelets with bruising) and pancytopenia (all blood cells low), as well as eosinophilia (raised eosinophils)."),
    c("chlorpromazine", "urgent-help", ADVERSE, "Warn patients to report the sudden appearance of sore throat or other signs of infection.", "Report the sudden appearance of a sore throat or other signs of infection to your prescriber."),
    c("chlorpromazine", "monitoring", ADVERSE, "Most cases have occurred between the fourth and tenth weeks of therapy; patients should be watched closely during that period.", "Most cases of agranulocytosis (a serious drop in white blood cells) have occurred between the fourth and tenth weeks of treatment, so you should be watched closely during that period."),
    c("chlorpromazine", "side-effects", ADVERSE, "Postural hypotension, simple tachycardia, momentary fainting and dizziness may occur rarely, after the first oral dose.", "Low blood pressure on standing (postural hypotension), a simple fast heartbeat, brief fainting and dizziness may occur, rarely, after the first oral dose."),
    c("chlorpromazine", "side-effects", ADVERSE, "Neuromuscular reactions include dystonias, motor restlessness, pseudo-parkinsonism and tardive dyskinesia, and appear to be dose-related.", "Muscle and nerve (neuromuscular) reactions include dystonias (muscle spasms), motor restlessness, pseudo-parkinsonism (Parkinson-like symptoms) and tardive dyskinesia (abnormal movements), and appear to be related to the dose."),
    c("chlorpromazine", "side-effects", ADVERSE, "Sudden death, apparently due to cardiac arrest, has been reported.", "Sudden death, apparently due to cardiac arrest (the heart stopping), has been reported."),

    /* ---- buspirone tablets ---- */
    c("buspirone", "used-for", IND, "Buspirone hydrochloride tablets are indicated for the management of anxiety disorders or the short-term relief of the symptoms of anxiety. Anxiety or tension associated with the stress of everyday life usually does not require treatment with an anxiolytic.", "Buspirone is used to manage anxiety disorders or to give short-term relief of the symptoms of anxiety. The label says anxiety or tension from the stress of everyday life usually does not need treatment with an anxiety medicine (anxiolytic)."),
    c("buspirone", "precaution", IND, "The effectiveness of buspirone hydrochloride tablets in long-term use, that is, for more than 3 to 4 weeks, has not been demonstrated in controlled trials.", "Controlled trials have not shown that buspirone keeps working when used for a long time (more than 3 to 4 weeks)."),
    c("buspirone", "monitoring", IND, "the physician who elects to use buspirone hydrochloride tablets for extended periods should periodically reassess the usefulness of the drug for the individual patient.", "If buspirone is used for a long period, your prescriber should regularly reassess whether it is still useful for you."),
    c("buspirone", "contraindication", CONTRA, "Buspirone hydrochloride tablets are contraindicated in patients hypersensitive to buspirone hydrochloride.", "Do not take it if you are known to be hypersensitive (allergic) to buspirone."),
    c("buspirone", "interactions", CONTRA, "The use of monoamine oxidase inhibitors (MAOIs) intended to treat depression with buspirone or within 14 days of stopping treatment with buspirone is contraindicated because of an increased risk of serotonin syndrome and/or elevated blood pressure. The use of buspirone within 14 days of stopping an MAOI intended to treat depression is also contraindicated.", "Do not use an MAOI antidepressant (a monoamine oxidase inhibitor) with buspirone, or within 14 days of stopping buspirone, because of an increased risk of serotonin syndrome and/or high blood pressure. Do not use buspirone within 14 days of stopping an MAOI antidepressant either."),
    c("buspirone", "how-to-take", DOSE, "The bioavailability of buspirone is increased when given with food as compared to the fasted state (see CLINICAL PHARMACOLOGY). Consequently, patients should take buspirone in a consistent manner with regard to the timing of dosing; either always with or always without food.", "Food increases how much buspirone your body takes in. So take it the same way every time: either always with food or always without food."),
    c("buspirone", "how-to-take", DOSE, "The recommended initial dose is 15 mg daily (7.5 mg b.i.d.). To achieve an optimal therapeutic response, at intervals of 2 to 3 days the dosage may be increased 5 mg per day, as needed. The maximum daily dosage should not exceed 60 mg per day.", "The label gives a recommended starting dose of 15 mg a day (7.5 mg twice a day). It may be increased by 5 mg a day every 2 to 3 days as needed, and the maximum is 60 mg a day. Your own dose is set by your prescriber.", ["US prescribing information, which is written for clinicians: this restates it in plain words.", "These are the doses in the US label. Do not use them to change your own dose.", "US label only: Indian approval, strengths and warnings may differ."]),
    c("buspirone", "side-effects", ADVERSE, "The more commonly observed untoward events associated with the use of buspirone hydrochloride tablets not seen at an equivalent incidence among placebo-treated patients include dizziness, nausea, headache, nervousness, lightheadedness, and excitement.", "The side effects more commonly seen with buspirone than with a dummy tablet (placebo) include dizziness, nausea, headache, nervousness, lightheadedness and excitement."),

    /* ---- propranolol tablets ---- */
    c("propranolol", "used-for", IND, "Propranolol hydrochloride tablets, USP are indicated in the management of hypertension. It may be used alone or used in combination with other antihypertensive agents, particularly a thiazide diuretic.", "Propranolol is used to manage high blood pressure (hypertension), alone or with other blood pressure medicines, particularly a thiazide diuretic (water tablet)."),
    c("propranolol", "used-for", IND, "Propranolol hydrochloride tablets, USP are indicated to decrease angina frequency and increase exercise tolerance in patients with angina pectoris.", "It is used to reduce how often angina (chest pain from the heart) occurs and to improve exercise tolerance in people with angina."),
    c("propranolol", "used-for", IND, "Propranolol hydrochloride tablets, USP are indicated to control ventricular rate in patients with atrial fibrillation and a rapid ventricular response.", "It is used to control the heart rate in people with atrial fibrillation (an irregular heartbeat) and a rapid ventricular response (a fast heartbeat)."),
    c("propranolol", "used-for", IND, "Propranolol hydrochloride tablets, USP are indicated to reduce cardiovascular mortality in patients who have survived the acute phase of myocardial infarction and are clinically stable.", "It is used to reduce deaths from heart and blood vessel disease in people who have survived the acute phase of a heart attack (myocardial infarction) and are clinically stable."),
    c("propranolol", "used-for", IND, "Propranolol hydrochloride tablets, USP are indicated for the prophylaxis of common migraine headache. The efficacy of propranolol in the treatment of a migraine attack that has started has not been established, and propranolol is not indicated for such use.", "It is used to prevent common migraine headaches. It has not been shown to treat a migraine attack that has already started, and it is not meant for that."),
    c("propranolol", "used-for", IND, "Propranolol hydrochloride tablets, USP are indicated in the management of familial or hereditary essential tremor.", "It is used to manage familial or hereditary essential tremor (shaking of the hands and arms that runs in families). The label says it is not for tremor caused by Parkinson's disease."),
    c("propranolol", "contraindication", CONTRA, "Propranolol is contraindicated in 1) cardiogenic shock; 2) sinus bradycardia and greater than first degree block; 3) bronchial asthma; and 4) in patients with known hypersensitivity to propranolol hydrochloride.", "Propranolol must not be used in cardiogenic shock (a failing heart that cannot supply the body), in a slow heartbeat called sinus bradycardia or in heart block beyond the first degree, in bronchial asthma, or by people who are known to be hypersensitive (allergic) to it."),
    c("propranolol", "stopping", WARN, "There have been reports of exacerbation of angina and, in some cases, myocardial infarction, following abrupt discontinuance of propranolol therapy. Therefore, when discontinuance of propranolol is planned, the dosage should be gradually reduced over at least a few weeks and the patient should be cautioned against interruption or cessation of therapy without the physician's advice.", "Angina has got worse, and in some cases a heart attack has occurred, after propranolol was stopped suddenly. When stopping is planned, the dose should be reduced gradually over at least a few weeks. Do not interrupt or stop it without your doctor's advice."),
    c("propranolol", "precaution", WARN, "In general, patients with bronchospastic lung disease should not receive beta blockers. Propranolol should be administered with caution in this setting since it may provoke a bronchial asthmatic attack by blocking bronchodilation produced by endogenous and exogenous catecholamine stimulation of beta-receptors.", "In general, people with bronchospastic lung disease (lungs that tighten and narrow the airways) should not receive beta blockers such as propranolol. If it is used, it needs caution, because it may provoke an asthma attack."),
    c("propranolol", "precaution", WARN, "Sympathetic stimulation may be a vital component supporting circulatory function in patients with congestive heart failure, and its inhibition by beta blockade may precipitate more severe failure.", "In people with congestive heart failure, the body's natural stimulation of the heart may be vital, and blocking it with a beta blocker such as propranolol may make the failure more severe."),
    c("propranolol", "precaution", WARN, "Beta-adrenergic blockade may prevent the appearance of certain premonitory signs and symptoms (pulse rate and pressure changes) of acute hypoglycemia, especially in labile insulin-dependent diabetics.", "Propranolol may hide some early warning signs of low blood sugar (changes in pulse rate and blood pressure), especially in people on insulin whose blood sugar swings widely."),
    c("propranolol", "precaution", WARN, "Chronically administered beta-blocking therapy should not be routinely withdrawn prior to major surgery, however the impaired ability of the heart to respond to reflex adrenergic stimuli may augment the risks of general anesthesia and surgical procedures.", "Long-term beta-blocker treatment should not routinely be stopped before major surgery, but the heart's weakened ability to respond to reflexes may add to the risks of general anaesthesia and surgery. Tell the surgical team you take propranolol."),
    c("propranolol", "precaution", WARN, "Beta-adrenergic blockade may mask certain clinical signs of hyperthyroidism. Therefore, abrupt withdrawal of propranolol may be followed by an exacerbation of symptoms of hyperthyroidism, including thyroid storm.", "Propranolol may hide some signs of an overactive thyroid (hyperthyroidism). Stopping it suddenly may be followed by worse thyroid symptoms, including thyroid storm (a dangerous flare of thyroid overactivity)."),
    c("propranolol", "how-to-take", DOSE, "Because of the variable bioavailability of propranolol, the dose should be individualized based on response.", "How much of propranolol your body absorbs varies, so your dose should be individualised according to how you respond."),
    c("propranolol", "onset", DOSE, "The time needed for full antihypertensive response to a given dosage is variable and may range from a few days to several weeks.", "For high blood pressure, the label says the time needed for the full response to a given dose varies and may range from a few days to several weeks.", ["This is stated for the treatment of high blood pressure (hypertension), not for every use of propranolol.", "US prescribing information, which is written for clinicians: this restates it in plain words.", "US label only: Indian approval, strengths and warnings may differ."], "onset-works-gradually"),
    c("propranolol", "side-effects", ADVERSE, "Cardiovascular: Bradycardia; congestive heart failure; intensification of AV block; hypotension; paresthesia of hands; thrombocytopenic purpura; arterial insufficiency, usually of the Raynaud type.", "Listed effects on the heart and circulation: a slow heartbeat (bradycardia), congestive heart failure, worsening of heart block (AV block), low blood pressure, tingling in the hands, thrombocytopenic purpura (low platelets with bruising), and poor blood flow to the fingers and toes, usually of the Raynaud type.", LIST_PI),
    c("propranolol", "side-effects", ADVERSE, "Central Nervous System: Light-headedness, mental depression manifested by insomnia, lassitude, weakness, fatigue; catatonia; visual disturbances; hallucinations; vivid dreams;", "Listed effects on the brain and nerves: light-headedness; mental depression with insomnia, lack of energy (lassitude), weakness and tiredness; catatonia; visual disturbances; hallucinations; and vivid dreams.", LIST_PI),
    c("propranolol", "side-effects", ADVERSE, "Gastrointestinal: Nausea, vomiting, epigastric distress, abdominal cramping, diarrhea, constipation,", "Listed effects on the stomach and bowel: nausea, vomiting, upper stomach discomfort, abdominal cramps, diarrhoea and constipation.", LIST_PI),
    c("propranolol", "side-effects", ADVERSE, "Respiratory: Bronchospasm.", "Listed effect on the lungs: bronchospasm (tightening of the airways).", LIST_PI),

    /* ---- clonidine tablets ---- */
    c("clonidine", "used-for", IND, "Clonidine hydrochloride is indicated in the treatment of hypertension. Clonidine hydrochloride may be employed alone or concomitantly with other antihypertensive agents.", "This label for clonidine tablets says it is used to treat high blood pressure (hypertension), alone or with other blood pressure medicines. It does not describe other uses of clonidine.", ["This is the label for clonidine tablets for high blood pressure. Other uses and forms of clonidine are not covered.", "US prescribing information, which is written for clinicians: this restates it in plain words.", "US label only: Indian approval, strengths and warnings may differ."]),
    c("clonidine", "contraindication", CONTRA, "Clonidine hydrochloride tablets USP should not be used in patients with known hypersensitivity to clonidine", "Clonidine tablets should not be used if you are known to be hypersensitive (allergic) to clonidine."),
    c("clonidine", "stopping", WARN, "Patients should be instructed not to discontinue therapy without consulting their physician. Sudden cessation of clonidine treatment has, in some cases, resulted in symptoms such as nervousness, agitation, headache, and tremor accompanied or followed by a rapid rise in blood pressure and elevated catecholamine concentrations in the plasma.", "Do not stop clonidine without consulting your doctor. Stopping suddenly has, in some cases, caused nervousness, agitation, headache and tremor, accompanied or followed by a rapid rise in blood pressure."),
    c("clonidine", "stopping", WARN, "Rare instances of hypertensive encephalopathy, cerebrovascular accidents and death have been reported after clonidine withdrawal. When discontinuing therapy with clonidine hydrochloride, the physician should reduce the dose gradually over 2 to 4 days to avoid withdrawal symptomatology.", "Rare cases of hypertensive encephalopathy (brain swelling from very high blood pressure), stroke (cerebrovascular accidents) and death have been reported after clonidine was withdrawn. When stopping, the doctor should reduce the dose gradually over 2 to 4 days to avoid withdrawal symptoms."),
    c("clonidine", "interactions", WARN, "The likelihood of such reactions to discontinuation of clonidine therapy appears to be greater after administration of higher doses or continuation of concomitant beta-blocker treatment and special caution is therefore advised in these situations.", "Reactions to stopping clonidine seem more likely after higher doses, or if a beta-blocker (another type of blood pressure medicine) is continued at the same time, so special caution is advised in these situations."),
    c("clonidine", "precaution", PC, "Since patients may experience a possible sedative effect, dizziness, or accommodation disorder with use of clonidine, caution patients about engaging in activities such as driving a vehicle or operating appliances or machinery. Also, inform patients that this sedative effect may be increased by concomitant use of alcohol, barbiturates, or other sedating drugs.", "Clonidine can cause sedation (sleepiness), dizziness or trouble focusing the eyes (accommodation disorder), so be careful with activities such as driving or operating appliances or machinery. The sleepiness may be increased if you also use alcohol, barbiturates or other sedating medicines."),
    c("clonidine", "precaution", PC, "Patients who wear contact lenses should be cautioned that treatment with clonidine hydrochloride may cause dryness of eyes.", "If you wear contact lenses, be aware that clonidine may cause dry eyes."),
    c("clonidine", "how-to-take", DOSE, "The dose of clonidine hydrochloride USP must be adjusted according to the patient's individual blood pressure response.", "Your dose is adjusted according to your own blood pressure response. Your prescriber decides it, not you."),
    c("clonidine", "how-to-take", DOSE, "Taking the larger portion of the oral daily dose at bedtime may minimize transient adjustment effects of dry mouth and drowsiness.", "Taking the larger part of the daily dose at bedtime may reduce the temporary dry mouth and drowsiness while your body adjusts."),
    c("clonidine", "side-effects", ADVERSE, "Most adverse effects are mild and tend to diminish with continued therapy. The most frequent (which appear to be dose-related) are dry mouth, occurring in about 40 of 100 patients; drowsiness, about 33 in 100; dizziness, about 16 in 100; constipation and sedation, each about 10 in 100.", "Most side effects are mild and tend to lessen with continued treatment. The most frequent, which appear to depend on the dose, are dry mouth (about 40 in 100 patients), drowsiness (about 33 in 100), dizziness (about 16 in 100), and constipation and sedation (each about 10 in 100).", ["US prescribing information, which is written for clinicians: this restates it in plain words.", "Figures come from US studies and cannot predict how common a side effect is for any one person.", "US label only: Indian approval, strengths and warnings may differ."]),

    /* ---- hydroxyzine tablets ---- */
    c("hydroxyzine", "used-for", IND, "For symptomatic relief of anxiety and tension associated with psychoneurosis and as an adjunct in organic disease states in which anxiety is manifested.", "Hydroxyzine is used for symptomatic relief of anxiety and tension associated with psychoneurosis (an older medical term for anxiety-related conditions), and as an add-on in physical illnesses in which anxiety shows."),
    c("hydroxyzine", "used-for", IND, "Useful in the management of pruritus due to allergic conditions such as chronic urticaria and atopic and contact dermatoses and in histamine-mediated pruritus.", "It is useful for managing itching (pruritus) caused by allergic conditions such as chronic hives (urticaria) and eczema-type skin conditions (atopic and contact dermatoses), and itching caused by histamine."),
    c("hydroxyzine", "used-for", IND, "As a sedative when used as a premedication and following general anesthesia,", "It is also used as a sedative before and after general anaesthesia."),
    c("hydroxyzine", "precaution", IND, "The effectiveness of hydroxyzine as an antianxiety agent for long term use, that is more than 4 months, has not been assessed by systematic clinical studies. The physician should reassess periodically the usefulness of the drug for the individual patient.", "Studies have not systematically assessed how well hydroxyzine works as an anti-anxiety medicine over long use (more than 4 months). Your prescriber should reassess from time to time whether it is still useful for you."),
    c("hydroxyzine", "contraindication", CONTRA, "Oral hydroxyzine hydrochloride is contraindicated in patients with known hypersensitivity to hydroxyzine hydrochloride products, and in patients with known hypersensitivity to cetirizine hydrochloride or levocetirizine hydrochloride. Hydroxyzine is contraindicated in patients with a prolonged QT interval.", "Do not take oral hydroxyzine if you are known to be hypersensitive (allergic) to hydroxyzine products, cetirizine or levocetirizine, or if you have a prolonged QT interval (a heart rhythm change seen on an ECG)."),
    c("hydroxyzine", "contraindication", CONTRA, "Clinical data in human beings are inadequate to establish safety in early pregnancy. Until such data are available, hydroxyzine is contraindicated in early pregnancy.", "There are not enough data in people to show that hydroxyzine is safe in early pregnancy, so it must not be used in early pregnancy."),
    c("hydroxyzine", "precaution", WARN, "It is not known whether this drug is excreted in human milk. Since many drugs are so excreted, hydroxyzine should not be given to nursing mothers.", "It is not known whether hydroxyzine passes into breast milk. Because many medicines do, it should not be given to nursing mothers."),
    c("hydroxyzine", "how-to-take", DOSE, "As with all potent medication, the dosage should be adjusted according to the patient’s response to therapy.", "As with all potent medicines, the dose should be adjusted according to how you respond. Your prescriber decides it, not you."),
    c("hydroxyzine", "side-effects", ADVERSE, "Side effects reported with the administration of hydroxyzine hydrochloride are usually mild and transitory in nature. Anticholinergic: Dry mouth. Central Nervous System: Drowsiness is usually transitory and may disappear in a few days of continued therapy or upon reduction of dose.", "Side effects are usually mild and short-lived. Dry mouth can occur. Drowsiness is usually temporary and may disappear within a few days of continued treatment, or when the dose is reduced."),
    c("hydroxyzine", "side-effects", ADVERSE, "Involuntary motor activity including rare instances of tremor and convulsions have been reported, usually with doses considerably higher than those recommended.", "Involuntary movements, including rare cases of tremor and convulsions (fits), have been reported, usually with doses much higher than those recommended."),
    c("hydroxyzine", "side-effects", ADVERSE, "Cardiac System: QT prolongation, Torsade de Pointes.", "Heart rhythm changes have been reported: QT prolongation and Torsade de Pointes (a dangerous irregular heart rhythm)."),
    c("hydroxyzine", "side-effects", ADVERSE, "Oral hydroxyzine is associated with Acute Generalized Exanthematous Pustulosis (AGEP) and fixed drug eruptions in postmarketing reports; pruritus, rash, urticaria.", "Reports after the medicine was on the market link oral hydroxyzine to skin reactions: acute generalized exanthematous pustulosis (AGEP, a sudden widespread rash with small pus-filled spots), fixed drug eruptions (a rash that returns in the same place), itching, rash and hives (urticaria)."),

    /* ---- trihexyphenidyl tablets ---- */
    c("trihexyphenidyl", "used-for", IND, "This drug is indicated as an adjunct in the treatment of all forms of parkinsonism (postencephalitic, arteriosclerotic, and idiopathic). It is often useful as adjuvant therapy when treating these forms of parkinsonism with levodopa.", "Trihexyphenidyl is used as an add-on treatment for all forms of parkinsonism (postencephalitic, arteriosclerotic and idiopathic). It is often useful as an add-on when these forms are treated with levodopa."),
    c("trihexyphenidyl", "used-for", IND, "Additionally, it is indicated for the control of extrapyramidal disorders caused by central nervous system drugs such as the dibenzoxazepines, phenothiazines, thioxanthenes, and butyrophenones.", "It is also used to control extrapyramidal disorders (movement problems) caused by medicines that act on the brain, such as dibenzoxazepines, phenothiazines, thioxanthenes and butyrophenones (groups of antipsychotic medicines)."),
    c("trihexyphenidyl", "precaution", WARN, "Patients to be treated with trihexyphenidyl HCl should have a gonioscope evaluation and close monitoring of intraocular pressures at regular periodic intervals.", "People treated with trihexyphenidyl should have an eye examination (gonioscopy) and regular, close checks of the pressure inside the eye."),
    c("trihexyphenidyl", "precaution", ADVERSE, "Patients with arteriosclerosis or with a history of idiosyncrasy to other drugs may exhibit reactions of mental confusion, agitation, disturbed behavior, or nausea and vomiting.", "People with arteriosclerosis (hardened arteries), or who have reacted unusually to other medicines before, may get mental confusion, agitation, disturbed behaviour, or nausea and vomiting."),
    c("trihexyphenidyl", "precaution", ADVERSE, "Psychiatric disturbances can result from indiscriminate use (leading to overdosage) to sustain continued euphoria.", "Psychiatric disturbances can result from using it carelessly (leading to overdose) to keep up a feeling of euphoria."),
    c("trihexyphenidyl", "how-to-take", DOSE, "Dosage should be individualized. The initial dose should be low and then increased gradually, especially in patients over 60 years of age.", "Your dose should be set for you. It should start low and be increased gradually, especially in people over 60 years of age."),
    c("trihexyphenidyl", "how-to-take", DOSE, "Whether trihexyphenidyl HCl may best be given before or after meals should be determined by the way the patient reacts.", "Whether it is best taken before or after meals depends on how you react to it."),
    c("trihexyphenidyl", "how-to-take", DOSE, "If trihexyphenidyl HCl tends to dry the mouth excessively, it may be better to take it before meals, unless it causes nausea. If taken after meals, the thirst sometimes induced can be allayed by mint candies, chewing gum or water.", "If it dries your mouth too much, it may be better to take it before meals, unless it causes nausea. If you take it after meals, any thirst it causes can be eased with mint candies, chewing gum or water."),
    c("trihexyphenidyl", "side-effects", ADVERSE, "Minor side effects, such as dryness of the mouth, blurring of vision, dizziness, mild nausea, or nervousness, will be experienced by 30 to 50 percent of all patients.", "Minor side effects such as dry mouth, blurred vision, dizziness, mild nausea or nervousness will be experienced by 30 to 50 percent of patients."),
    c("trihexyphenidyl", "side-effects", ADVERSE, "Such reactions tend to become less pronounced, and even to disappear, as treatment continues. Even before these reactions have remitted spontaneously, they may often be controlled by careful adjustment of the dosage form, amount of drug, or interval between doses.", "These reactions tend to become less pronounced, and even to disappear, as treatment continues. Even before they ease on their own, they can often be controlled by carefully adjusting the dosage form, the amount of medicine, or the time between doses."),
    c("trihexyphenidyl", "side-effects", ADVERSE, "Potential side effects associated with the use of any atropine-like drugs include constipation, drowsiness, urinary hesitancy or retention, tachycardia, dilation of the pupil, increased intraocular tension, weakness, vomiting, and headache.", "Side effects possible with any atropine-like (drying) medicine include constipation, drowsiness, difficulty starting to pass urine or not being able to pass it, a fast heartbeat, widened pupils, raised pressure in the eye, weakness, vomiting and headache."),
    c("trihexyphenidyl", "side-effects", ADVERSE, "The occurrence of angle-closure glaucoma due to long-term treatment with trihexyphenidyl hydrochloride has been reported.", "Angle-closure glaucoma (a sudden rise of eye pressure) has been reported with long-term treatment."),
    c("trihexyphenidyl", "side-effects", ADVERSE, "Isolated instances of suppurative parotitis secondary to excessive dryness of the mouth, skin rashes, dilatation of the colon, paralytic ileus, and certain psychiatric manifestations such as delusions and hallucinations, plus one doubtful case of paranoia all of which may occur with any of the atropine-like drugs, have been rarely reported with trihexyphenidyl hydrochloride.", "Rarely reported: infection of the salivary gland (suppurative parotitis) from a very dry mouth, skin rashes, widening of the colon, a blocked bowel (paralytic ileus), and psychiatric effects such as delusions and hallucinations, plus one doubtful case of paranoia. All of these may occur with any atropine-like drug."),

    /* ---- benztropine tablets ---- */
    c("benztropine", "used-for", IND, "For use as an adjunct in the therapy of all forms of parkinsonism.", "Benztropine is used as an add-on treatment for all forms of parkinsonism."),
    c("benztropine", "used-for", IND, "Useful also in the control of extrapyramidal disorders (except tardive dyskinesia", "It is also useful for controlling extrapyramidal disorders (movement problems), but the label excepts tardive dyskinesia."),
    c("benztropine", "used-for", IND, "due to neuroleptic drugs (e.g., phenothiazines).", "The movement problems it is used for are those caused by neuroleptic (antipsychotic) drugs, for example phenothiazines."),
    c("benztropine", "contraindication", CONTRA, "Hypersensitivity to benztropine mesylate tablets. Because of its atropine-like side effects, this drug is contraindicated in pediatric patients under three years of age, and should be used with caution in older pediatric patients.", "Do not take it if you are hypersensitive (allergic) to benztropine tablets. Because of its atropine-like side effects, it must not be given to children under three years of age and needs caution in older children."),
    c("benztropine", "precaution", WARN, "Safe use in pregnancy has not been established.", "Safe use in pregnancy has not been established."),
    c("benztropine", "precaution", WARN, "Benztropine mesylate may impair mental and/or physical abilities required for performance of hazardous tasks, such as operating machinery or driving a motor vehicle.", "It may impair the mental and/or physical abilities needed for hazardous tasks such as operating machinery or driving."),
    c("benztropine", "urgent-help", WARN, "When benztropine mesylate is given concomitantly with phenothiazines, haloperidol, or other drugs with anticholinergic or antidopaminergic activity, patients should be advised to report gastrointestinal complaints, fever or heat intolerance promptly.", "If you take benztropine with phenothiazines, haloperidol or other medicines with drying (anticholinergic) or dopamine-blocking (antidopaminergic) effects, report stomach and bowel complaints, fever or heat intolerance promptly."),
    c("benztropine", "side-effects", WARN, "Paralytic ileus, hyperthermia and heat stroke, all of which have sometimes been fatal, have occurred in patients taking anticholinergic-type antiparkinsonism drugs, including benztropine mesylate, in combination with phenothiazines and/or tricyclic antidepressants.", "A blocked bowel (paralytic ileus), a very high body temperature (hyperthermia) and heat stroke, all of which have sometimes been fatal, have occurred in people taking drying (anticholinergic) anti-parkinsonism medicines, including benztropine, together with phenothiazines and/or tricyclic antidepressants."),
    c("benztropine", "precaution", WARN, "Since benztropine mesylate contains structural features of atropine, it may produce anhidrosis. For this reason, it should be administered with caution during hot weather, especially when given concomitantly with other atropine-like drugs to the chronically ill, the alcoholic, those who have central nervous system disease, and those who do manual labor in a hot environment.", "Because it is built like atropine, benztropine may stop you sweating (anhidrosis). It needs caution in hot weather, especially with other atropine-like drugs, in people who are chronically ill or alcoholic, who have central nervous system disease, or who do manual labour in a hot place."),
    c("benztropine", "how-to-take", DOSE, "Because of cumulative action, therapy should be initiated with a low dose which is increased gradually at five- or six-day intervals to the smallest amount necessary for optimal relief.", "Because the effect builds up, treatment should start with a low dose that is increased gradually at five- or six-day intervals to the smallest amount needed for the best relief."),
    c("benztropine", "how-to-take", DOSE, "Some patients experience greatest relief by taking the entire dose at bedtime; others react more favorably to divided doses, two to four times a day.", "Some people get the greatest relief taking the whole dose at bedtime; others do better with divided doses two to four times a day."),
    c("benztropine", "side-effects", ADVERSE, "Digestive Paralytic ileus, constipation, vomiting, nausea, dry mouth.", "Digestive effects listed: a blocked bowel (paralytic ileus), constipation, vomiting, nausea and dry mouth."),
    c("benztropine", "monitoring", ADVERSE, "If dry mouth is so severe that there is difficulty in swallowing or speaking, or loss of appetite and weight, reduce dosage or discontinue the drug temporarily.", "If dry mouth is so severe that you have difficulty swallowing or speaking, or lose appetite and weight, tell your prescriber: the label says to reduce the dose or stop the medicine temporarily."),
    c("benztropine", "side-effects", ADVERSE, "Toxic psychosis, including confusion, disorientation, memory impairment, visual hallucinations; exacerbation of pre-existing psychotic symptoms; nervousness; depression; listlessness; numbness of fingers.", "Nervous system effects listed: toxic psychosis (including confusion, disorientation, memory impairment and visual hallucinations), worsening of existing psychotic symptoms, nervousness, depression, listlessness and numbness of the fingers."),
    c("benztropine", "side-effects", ADVERSE, "Special Senses Blurred vision, dilated pupils. Urogenital Urinary retention, dysuria.", "Listed effects on the eyes and bladder: blurred vision, widened pupils, urinary retention (not being able to pass urine) and dysuria (painful passing of urine)."),

    /* ---- disulfiram tablets ---- */
    c("disulfiram", "used-for", IND, "Disulfiram is an aid in the management of selected chronic alcohol patients who want to remain in a state of enforced sobriety so that supportive and psychotherapeutic treatment may be applied to best advantage. Disulfiram is not a cure for alcoholism.", "Disulfiram is an aid for some people with long-term alcohol problems who want to stay sober, so that supportive treatment and counselling can be used to best effect. The label says it is not a cure for alcoholism."),
    c("disulfiram", "precaution", IND, "When used alone, without proper motivation and supportive therapy, it is unlikely that it will have any substantive effect on the drinking pattern of the chronic alcoholic.", "Used alone, without proper motivation and supportive treatment, it is unlikely to have any real effect on the drinking pattern of a person with a long-term alcohol problem."),
    c("disulfiram", "precaution", BOX, "Disulfiram should never be administered to a patient when he is in a state of alcohol intoxication, or without his full knowledge. The physician should instruct relatives accordingly.", "Disulfiram should never be given to a person who is drunk, or without that person's full knowledge. The doctor should instruct relatives accordingly."),
    c("disulfiram", "precaution", WARN, "The patient must be fully informed of the disulfiram-alcohol reaction. He must be strongly cautioned against surreptitious drinking while taking the drug, and he must be fully aware of the possible consequences. He should be warned to avoid alcohol in disguised forms, i.e., in sauces, vinegars, cough mixtures, and even in aftershave lotions and back rubs. He should also be warned that reactions may occur with alcohol up to 14 days after ingesting disulfiram.", "You must be fully informed about the disulfiram-alcohol reaction and strongly cautioned against secret drinking while taking it. Avoid alcohol in disguised forms: in sauces, vinegars, cough mixtures, and even aftershave lotions and back rubs. Reactions may occur with alcohol up to 14 days after taking disulfiram."),
    c("disulfiram", "urgent-help", WARN, "Disulfiram plus alcohol, even small amounts, produce flushing, throbbing in head and neck, throbbing headache, respiratory difficulty, nausea, copious vomiting, sweating, thirst, chest pain, palpitation, dyspnea, hyperventilation, tachycardia, hypotension, syncope, marked uneasiness, weakness, vertigo, blurred vision, and confusion. In severe reactions there may be respiratory depression, cardiovascular collapse, arrhythmias, myocardial infarction, acute congestive heart failure, unconsciousness, convulsions, and death.", "Disulfiram with alcohol, even in small amounts, causes flushing, throbbing in the head and neck, a throbbing headache, trouble breathing, nausea, heavy vomiting, sweating, thirst, chest pain, a pounding heart, shortness of breath, fast breathing, a fast heartbeat, low blood pressure, fainting, marked uneasiness, weakness, vertigo, blurred vision and confusion. Severe reactions may include slowed breathing, collapse of the circulation, irregular heartbeat, heart attack, heart failure, loss of consciousness, convulsions and death. Get emergency help if this happens."),
    c("disulfiram", "side-effects", WARN, "The duration of the reaction varies from 30 to 60 minutes, to several hours in the more severe cases, or as long as there is alcohol in the blood.", "The reaction lasts from 30 to 60 minutes, to several hours in the more severe cases, or as long as there is alcohol in the blood."),
    c("disulfiram", "contraindication", CONTRA, "Disulfiram is contraindicated in the presence of severe myocardial disease or coronary occlusion, psychoses, and hypersensitivity to disulfiram or to other thiuram derivatives used in pesticides and rubber vulcanization.", "Disulfiram must not be used if you have severe heart muscle disease or a blocked coronary artery, a psychosis, or hypersensitivity (allergy) to disulfiram or to other thiuram chemicals used in pesticides and rubber making."),
    c("disulfiram", "interactions", CONTRA, "Patients who are receiving or have recently received metronidazole, paraldehyde, alcohol, or alcohol-containing preparations, e.g., cough syrups, tonics and the like, should not be given disulfiram.", "Disulfiram should not be given to people who are receiving, or have recently received, metronidazole, paraldehyde, alcohol, or alcohol-containing preparations such as cough syrups and tonics."),
    c("disulfiram", "precaution", WARN, "Because of the possibility of an accidental disulfiram-alcohol reaction, disulfiram should be used with extreme caution in patients with any of the following conditions: diabetes mellitus, hypothyroidism, epilepsy, cerebral damage, chronic and acute nephritis, hepatic cirrhosis or insufficiency.", "Because an accidental disulfiram-alcohol reaction is possible, disulfiram should be used with extreme caution in people with diabetes, an underactive thyroid (hypothyroidism), epilepsy, brain damage, kidney inflammation (nephritis), or cirrhosis or weak function of the liver."),
    c("disulfiram", "interactions", INTER, "Disulfiram appears to decrease the rate at which certain drugs are metabolized and therefore may increase the blood levels and the possibility of clinical toxicity of drugs given concomitantly.", "Disulfiram appears to slow how fast the body breaks down some medicines, so it may raise their levels in the blood and the chance that they become toxic."),
    c("disulfiram", "interactions", INTER, "DISULFIRAM SHOULD BE USED WITH CAUTION IN THOSE PATIENTS RECEIVING PHENYTOIN AND ITS CONGENERS, SINCE THE CONCOMITANT ADMINISTRATION OF THESE TWO DRUGS CAN LEAD TO PHENYTOIN INTOXICATION.", "Disulfiram should be used with caution in people taking phenytoin and similar medicines, because taking them together can lead to phenytoin poisoning."),
    c("disulfiram", "interactions", INTER, "It may be necessary to adjust the dosage of oral anticoagulants upon beginning or stopping disulfiram, since disulfiram may prolong prothrombin time.", "The dose of oral anticoagulants (blood thinners) may need adjusting when disulfiram is started or stopped, because disulfiram may lengthen the prothrombin time (a blood clotting test)."),
    c("disulfiram", "interactions", INTER, "Patients taking isoniazid when disulfiram is given should be observed for the appearance of unsteady gait or marked changes in mental status, the disulfiram should be discontinued if such signs appear.", "People taking isoniazid together with disulfiram should be watched for an unsteady walk or marked changes in mental state; disulfiram should be stopped if such signs appear."),
    c("disulfiram", "how-to-take", DOSE, "Disulfiram should never be administered until the patient has abstained from alcohol for at least 12 hours.", "Disulfiram should never be started until the person has avoided alcohol for at least 12 hours."),
    c("disulfiram", "how-to-take", DOSE, "Although usually taken in the morning, disulfiram may be taken on retiring by patients who experience a sedative effect.", "It is usually taken in the morning, but people who feel sleepy from it may take it at bedtime."),
    c("disulfiram", "how-to-take", DOSE, "The daily, uninterrupted administration of disulfiram must be continued until the patient is fully recovered socially and a basis for permanent self-control is established. Depending on the individual patient, maintenance therapy may be required for months or even years.", "Disulfiram must be taken every day, without interruption, until the person has fully recovered socially and a basis for permanent self-control is established. Depending on the person, treatment may be needed for months or even years."),
    c("disulfiram", "side-effects", ADVERSE, "OPTIC NEURITIS, PERIPHERAL NEURITIS, POLYNEURITIS, AND PERIPHERAL NEUROPATHY MAY OCCUR FOLLOWING ADMINISTRATION OF DISULFIRAM.", "Optic neuritis (inflammation of the nerve of the eye), peripheral neuritis, polyneuritis and peripheral neuropathy (damage or inflammation of nerves in the arms and legs) may occur after taking disulfiram."),
    c("disulfiram", "urgent-help", ADVERSE, "Multiple cases of hepatitis, including both cholestatic and fulminant hepatitis, as well as hepatic failure resulting in transplantation or death, have been reported with administration of disulfiram.", "Many cases of hepatitis (inflammation of the liver), including cholestatic hepatitis and fulminant (sudden, severe) hepatitis, as well as liver failure leading to a transplant or death, have been reported with disulfiram. Report signs of liver trouble to your doctor straight away."),
    c("disulfiram", "side-effects", ADVERSE, "In a small number of patients, a transient mild drowsiness, fatigability, impotence, headache, acneform eruptions, allergic dermatitis, or a metallic or garlic-like aftertaste may be experienced during the first two weeks of therapy. These complaints usually disappear spontaneously with the continuation of therapy, or with reduced dosage.", "In a small number of people, mild and temporary drowsiness, tiredness, impotence, headache, acne-like spots, allergic skin inflammation, or a metallic or garlic-like aftertaste may occur during the first two weeks. These complaints usually disappear on their own as treatment continues, or with a lower dose."),
    c("disulfiram", "side-effects", ADVERSE, "Psychotic reactions have been noted, attributable in most cases to high dosage, combined toxicity (with metronidazole or isoniazid), or to the unmasking of underlying psychoses in patients stressed by the withdrawal of alcohol.", "Psychotic reactions have been noted, in most cases linked to high doses, to combined toxicity with metronidazole or isoniazid, or to the unmasking of an underlying psychosis in people stressed by stopping alcohol."),

    /* ---- prazosin capsules ---- */
    c("prazosin", "used-for", IND, "Prazosin hydrochloride capsules, USP are indicated for the treatment of hypertension, to lower blood pressure.", "This label for prazosin capsules says they are used to treat high blood pressure (hypertension), to lower it. It does not describe other uses of prazosin.", ["This is the label for prazosin capsules for high blood pressure. Other uses are not covered.", "US prescribing information, which is written for clinicians: this restates it in plain words.", "US label only: Indian approval, strengths and warnings may differ."]),
    c("prazosin", "contraindication", CONTRA, "Prazosin hydrochloride capsules are contraindicated in patients with known sensitivity to quinazolines, prazosin, or any of the inert ingredients.", "Prazosin capsules must not be used by people with known sensitivity (allergy) to quinazolines, to prazosin, or to any of the inactive ingredients."),
    c("prazosin", "precaution", PC, "Dizziness or drowsiness may occur after the first dose of this medicine. Avoid driving or performing hazardous tasks for the first 24 hours after taking this medicine or when the dose is increased. Dizziness, light headedness, or fainting may occur, especially when rising from a lying or sitting position. Getting up slowly may help lessen the problem.", "Dizziness or drowsiness may occur after the first dose. Avoid driving or doing hazardous tasks for the first 24 hours after taking it, and again when the dose is increased. Dizziness, light-headedness or fainting may occur, especially when getting up from lying or sitting. Getting up slowly may help."),
    c("prazosin", "precaution", PC, "These effects may also occur if you drink alcohol, stand for long periods of time, exercise, or if the weather is hot. While taking prazosin hydrochloride capsules, be careful in the amount of alcohol you drink. Also, use extra care during exercise or hot weather, or if standing for long periods.", "These effects may also occur if you drink alcohol, stand for long periods, exercise, or if the weather is hot. Be careful how much alcohol you drink, and take extra care during exercise, in hot weather, or when standing for long periods."),
    c("prazosin", "urgent-help", WARN, "prazosin hydrochloride capsules may cause syncope with sudden loss of consciousness.", "Prazosin may cause syncope (fainting), with a sudden loss of consciousness."),
    c("prazosin", "side-effects", WARN, "Syncopal episodes have usually occurred within 30 to 90 minutes of the initial dose of the drug; occasionally, they have been reported in association with rapid dosage increases or the introduction of another antihypertensive drug into the regimen of a patient taking high doses of prazosin hydrochloride capsules.", "Fainting episodes have usually occurred within 30 to 90 minutes of the first dose. Occasionally they have been reported with rapid dose increases, or when another blood pressure medicine was added in a person taking high doses of prazosin."),
    c("prazosin", "precaution", WARN, "The patient should also be cautioned to avoid situations where injury could result should syncope occur during the initiation of prazosin hydrochloride therapy.", "Avoid situations where you could be injured if you faint when starting prazosin."),
    c("prazosin", "how-to-take", WARN, "Patients should always be started on the 1 mg capsules of prazosin hydrochloride. The 2 and 5 mg capsules are not indicated for initial therapy.", "Treatment should always be started with the 1 mg capsules. The 2 mg and 5 mg capsules are not meant for starting treatment."),
    c("prazosin", "how-to-take", DOSE, "The dose of prazosin hydrochloride capsules should be adjusted according to the patient’s individual blood pressure response.", "Your dose is adjusted according to your own blood pressure response. Your prescriber decides it, not you."),
    c("prazosin", "urgent-help", WARN, "Prolonged erections and priapism have been reported with alpha-1 blockers including prazosin in post-marketing experience. In the event of an erection that persists longer than 4 hours, seek immediate medical assistance.", "Prolonged erections and priapism (a painful, lasting erection) have been reported with alpha-1 blockers including prazosin. If an erection lasts longer than 4 hours, seek immediate medical help."),
    c("prazosin", "interactions", WARN, "Hypotension may develop in patients given prazosin hydrochloride capsules who are also receiving a beta-blocker such as propranolol.", "Low blood pressure may develop in people taking prazosin together with a beta-blocker such as propranolol."),
    c("prazosin", "interactions", INTER, "Addition of a diuretic or other antihypertensive agent to prazosin hydrochloride has been shown to cause an additive hypotensive effect.", "Adding a diuretic (water tablet) or another blood pressure medicine to prazosin has been shown to lower blood pressure further."),
    c("prazosin", "interactions", INTER, "Concomitant administration of prazosin hydrochloride with a phosphodiesterase-5 (PDE-5) inhibitor can result in additive blood pressure lowering effects and symptomatic hypotension", "Taking prazosin together with a phosphodiesterase-5 (PDE-5) inhibitor (a type of medicine for erection problems) can lower blood pressure further and cause low blood pressure with symptoms."),
    c("prazosin", "side-effects", ADVERSE, "the most frequent reactions associated with prazosin hydrochloride capsules therapy are: dizziness 10.3%, headache 7.8%, drowsiness 7.6%, lack of energy 6.9%, weakness 6.5%, palpitations 5.3%, and nausea 4.9%. In most instances, side effects have disappeared with continued therapy or have been tolerated with no decrease in dose of drug.", "The most frequent side effects were dizziness (10.3%), headache (7.8%), drowsiness (7.6%), lack of energy (6.9%), weakness (6.5%), palpitations (5.3%) and nausea (4.9%). In most cases side effects disappeared with continued treatment or were tolerated without lowering the dose.", ["US prescribing information, which is written for clinicians: this restates it in plain words.", "Figures come from US trials and cannot predict how common a side effect is for any one person.", "US label only: Indian approval, strengths and warnings may differ."]),

    /* ---- fluphenazine tablets ---- */
    c("fluphenazine", "used-for", IND, "Fluphenazine hydrochloride tablets are indicated in the management of manifestations of psychotic disorders.", "Fluphenazine is used in the management of the symptoms of psychotic disorders."),
    c("fluphenazine", "precaution", IND, "Fluphenazine hydrochloride has not been shown effective in the management of behavioral complications in patients with mental retardation.", "It has not been shown to work for behavioural complications in people with intellectual disability (the label's term is mental retardation)."),
    c("fluphenazine", "precaution", BOX, "Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death.", "Elderly people with dementia-related psychosis who are treated with antipsychotic medicines are at an increased risk of death. The label says fluphenazine is not approved for treating dementia-related psychosis."),
    c("fluphenazine", "contraindication", CONTRA, "Phenothiazines are contraindicated in patients with suspected or established subcortical brain damage, in patients receiving large doses of hypnotics, and in comatose or severely depressed states. The presence of blood dyscrasia or liver damage precludes the use of fluphenazine hydrochloride. Fluphenazine hydrochloride tablets are contraindicated in patients who have shown hypersensitivity to fluphenazine; cross-sensitivity to phenothiazine derivatives may occur.", "Phenothiazines (the group fluphenazine belongs to) must not be used in people with suspected or established brain damage deep in the brain (subcortical brain damage), people receiving large doses of sleeping medicines (hypnotics), or people in a coma or severely depressed state. A blood disorder (blood dyscrasia) or liver damage rules out fluphenazine. It must not be used by people who have shown hypersensitivity (allergy) to it, and an allergy to other phenothiazines may carry over."),
    c("fluphenazine", "how-to-take", DOSE, "The smallest amount that will produce the desired results must be carefully determined for each individual, since optimal dosage levels of this potent drug vary from patient to patient.", "The smallest dose that gives the desired results must be carefully worked out for each person, because the best dose of this potent medicine varies from person to person."),
    c("fluphenazine", "how-to-take", DOSE, "Treatment is best instituted with a low initial dosage, which may be increased, if necessary, until the desired clinical effects are achieved.", "Treatment is best started with a low dose, which may be increased if necessary until the desired effects are reached."),
    c("fluphenazine", "how-to-take", DOSE, "When symptoms are controlled, dosage can generally be reduced gradually to daily maintenance doses of 1 mg to 5 mg, often given as a single daily dose. Continued treatment is needed to achieve maximum therapeutic benefits", "When symptoms are controlled, the dose can generally be reduced gradually to a daily maintenance dose of 1 mg to 5 mg, often given as a single daily dose. Continued treatment is needed to get the maximum benefit. Your own dose is set by your prescriber.", ["US prescribing information, which is written for clinicians: this restates it in plain words.", "These are the figures in the US label. Do not use them to change your own dose.", "US label only: Indian approval, strengths and warnings may differ."]),
    c("fluphenazine", "side-effects", ADVERSE, "The side effects most frequently reported with phenothiazine compounds are extrapyramidal symptoms including pseudoparkinsonism, dystonia, dyskinesia, akathisia, oculogyric crises, opisthotonos, and hyperreflexia. Most often these extrapyramidal symptoms are reversible; however, they may be persistent", "The side effects most often reported with phenothiazines are extrapyramidal symptoms (movement problems): pseudoparkinsonism (Parkinson-like symptoms), dystonia (muscle spasms), dyskinesia (abnormal movements), akathisia (inner restlessness), oculogyric crises (the eyes turning upward), opisthotonos (arching of the back) and hyperreflexia (overactive reflexes). Most often they are reversible, but they may be persistent."),
    c("fluphenazine", "side-effects", ADVERSE, "Extrapyramidal reactions may be alarming, and the patient should be forewarned and reassured. These reactions can usually be controlled by administration of antiparkinsonian drugs such as benztropine mesylate or intravenous caffeine and sodium benzoate injection, and by subsequent reduction in dosage.", "These movement reactions may be alarming, and you should be warned about them in advance. They can usually be controlled with antiparkinsonian medicines such as benztropine, and by then lowering the dose."),
    c("fluphenazine", "urgent-help", ADVERSE, "Symptoms of dystonia, prolonged abnormal contractions of muscle groups, may occur in susceptible individuals during the first few days of treatment. Dystonic symptoms include: spasm of the neck muscles, sometimes progressing to tightness of the throat, swallowing difficulty, difficulty breathing, and/or protrusion of the tongue.", "Dystonia (long muscle spasms) may occur in susceptible people during the first few days of treatment. Symptoms include spasm of the neck muscles, sometimes progressing to tightness of the throat, trouble swallowing, trouble breathing and/or the tongue sticking out. Get medical help if this happens."),
    c("fluphenazine", "side-effects", PC, "Given the likelihood that some patients exposed chronically to neuroleptics will develop tardive dyskinesia, it is advised that all patients in whom chronic use is contemplated be given, if possible, full information about this risk.", "Because some people exposed over a long time to neuroleptics (antipsychotics) will develop tardive dyskinesia (abnormal movements that may be permanent), everyone for whom long-term use is planned should, if possible, be given full information about this risk."),

    /* ---- trifluoperazine tablets ---- */
    c("trifluoperazine", "used-for", IND, "For the management of schizophrenia.", "Trifluoperazine is used for the management of schizophrenia."),
    c("trifluoperazine", "used-for", IND, "Trifluoperazine hydrochloride tablets, USP are effective for the short-term treatment of generalized non-psychotic anxiety. However, trifluoperazine hydrochloride tablets are not the first drug to be used in therapy for most patients with non-psychotic anxiety because certain risks associated with its use are not shared by common alternative treatments (i.e., benzodiazepines).", "It is also effective for the short-term treatment of generalised anxiety that is not psychotic. But it is not the first medicine used for most people with this kind of anxiety, because some risks of using it are not shared by common alternatives (benzodiazepines)."),
    c("trifluoperazine", "precaution", IND, "When used in the treatment of non-psychotic anxiety, trifluoperazine hydrochloride tablets should not be administered at doses of more than 6 mg per day or for longer than 12 weeks because the use of trifluoperazine hydrochloride tablets at higher doses or for longer intervals may cause persistent tardive dyskinesia that may prove irreversible", "When used for non-psychotic anxiety, it should not be used at doses of more than 6 mg a day or for longer than 12 weeks, because higher doses or longer use may cause persistent tardive dyskinesia (abnormal movements) that may prove irreversible."),
    c("trifluoperazine", "precaution", BOX, "Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death.", "Elderly people with dementia-related psychosis who are treated with antipsychotic medicines are at an increased risk of death."),
    c("trifluoperazine", "contraindication", CONTRA, "A known hypersensitivity to phenothiazines, comatose or greatly depressed states due to central nervous system depressants and, in cases of existing blood dyscrasias, bone marrow depression and preexisting liver damage.", "It must not be used if you have a known hypersensitivity (allergy) to phenothiazines, in a coma or greatly depressed state caused by medicines or substances that slow the brain, or if you already have blood disorders, bone marrow depression or liver damage."),
    c("trifluoperazine", "how-to-take", DOSE, "Dosage should be adjusted to the needs of the individual. The lowest effective dosage should always be used. Dosage should be increased more gradually in debilitated or emaciated patients. When maximum response is achieved, dosage may be reduced gradually to a maintenance level.", "Your dose should be adjusted to your needs, and the lowest effective dose should always be used. The dose should be increased more gradually in people who are debilitated or very thin. When the maximum response is reached, the dose may be reduced gradually to a maintenance level."),
    c("trifluoperazine", "how-to-take", DOSE, "In general, dosages in the lower range are sufficient for most elderly patients. Since they appear to be more susceptible to hypotension and neuromuscular reactions, such patients should be observed closely.", "Elderly people usually need doses in the lower range. They appear more susceptible to low blood pressure and muscle and nerve reactions, so they should be watched closely."),
    c("trifluoperazine", "precaution", DOSE, "Although there is little likelihood of contact dermatitis due to the drug, persons with known sensitivity to phenothiazine drugs should avoid direct contact.", "There is little chance of a skin reaction from touching the drug, but people with known sensitivity to phenothiazines should avoid direct contact with it."),
    c("trifluoperazine", "side-effects", ADVERSE, "Drowsiness, dizziness, skin reactions, rash, dry mouth, insomnia, amenorrhea, fatigue, muscular weakness, anorexia, lactation, blurred vision and neuromuscular (extrapyramidal) reactions.", "Listed side effects: drowsiness, dizziness, skin reactions, rash, dry mouth, insomnia, missed periods (amenorrhea), tiredness, muscle weakness, loss of appetite, breast milk production (lactation), blurred vision, and neuromuscular (extrapyramidal) reactions (movement problems)."),
    c("trifluoperazine", "side-effects", ADVERSE, "They may be characterized by motor restlessness, be of the dystonic type, or they may resemble parkinsonism.", "The neuromuscular (extrapyramidal) reactions may show as motor restlessness, as dystonia (muscle spasms), or they may resemble parkinsonism."),
    c("trifluoperazine", "monitoring", ADVERSE, "Depending on the severity of symptoms, dosage should be reduced or discontinued.", "Depending on how severe these symptoms are, the dose should be reduced or the medicine stopped. Tell your prescriber if they occur."),
    c("trifluoperazine", "side-effects", ADVERSE, "Symptoms may include agitation or jitteriness and sometimes insomnia. These symptoms often disappear spontaneously.", "Motor restlessness may show as agitation or jitteriness and sometimes insomnia. These symptoms often disappear on their own."),
  ];
}
